def split(line):
    out = []
    cur = []
    in_word = False
    state = None  # None, "'" or '"'
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if state == "'":
            # Inside single quotes every character is literal.
            if ch == "'":
                state = None
            else:
                cur.append(ch)
            i += 1
        elif state == '"':
            # Inside double quotes: backslash before " or \ yields that
            # one character; any other backslash is kept as it is.
            if ch == '\\':
                if i + 1 < n and line[i + 1] in ('"', '\\'):
                    cur.append(line[i + 1])
                    i += 2
                else:
                    cur.append('\\')
                    i += 1
            elif ch == '"':
                state = None
                i += 1
            else:
                cur.append(ch)
                i += 1
        else:
            if ch == "'":
                state = "'"
                in_word = True
                i += 1
            elif ch == '"':
                state = '"'
                in_word = True
                i += 1
            elif ch == '\\':
                # Outside quotes a backslash makes the next character
                # literal; a backslash at the very end is kept as-is.
                if i + 1 < n:
                    cur.append(line[i + 1])
                    i += 2
                else:
                    cur.append('\\')
                    i += 1
                in_word = True
            elif ch.isspace():
                if in_word:
                    out.append(''.join(cur))
                    cur = []
                    in_word = False
                i += 1
            else:
                cur.append(ch)
                in_word = True
                i += 1
    if state is not None:
        raise ValueError('unterminated quote')
    if in_word:
        out.append(''.join(cur))
    return out

